process SEQKIT_SPLIT2 {
    tag "${meta.id}"
    label 'process_medium'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/29/297e985dd395d87f9089b314dbe685ddce59fa0770c4d1f5e1009bc7b6ec7a8d/data'
        : 'community.wave.seqera.io/library/seqkit:2.13.0--3bacfb68370dd835'}"

    input:
    tuple val(meta), path(reads)

    output:
    tuple val(meta), path("${prefix}/*"), emit: reads
    tuple val("${task.process}"), val('seqkit'), eval("seqkit version | sed 's/^.*v//'"), emit: versions_seqkit, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    prefix = task.ext.prefix ?: "${meta.id}"
    if (meta.single_end) {
        """
        seqkit \\
            split2 \\
            ${args} \\
            --threads ${task.cpus} \\
            ${reads} \\
            --out-dir ${prefix}
        """
    }
    else {
        """
        seqkit \\
            split2 \\
            ${args} \\
            --threads ${task.cpus} \\
            --read1 ${reads[0]} \\
            --read2 ${reads[1]} \\
            --out-dir ${prefix}
        """
    }

    stub:
    def args = task.ext.args ?: ''
    prefix = task.ext.prefix ?: "${meta.id}"
    if (meta.single_end) {
        """
        echo ${args}

        mkdir -p ${prefix}
        echo '' | gzip > ${prefix}/${reads[0]}
        """
    }
    else {
        """
        echo ${args}

        mkdir -p ${prefix}
        echo '' | gzip > ${prefix}/${reads[0]}
        echo '' | gzip > ${prefix}/${reads[1]}
        """
    }
}

nextflow_process {

    name "Test Process SEQKIT_SPLIT2"
    script "../main.nf"
    process "SEQKIT_SPLIT2"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "gunzip"
    tag "seqkit"
    tag "seqkit/split2"

    test("single_end - length") {
        when {
            params {
                modules_args = '--by-length 8K'
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

